+++ b/src/orchestration/chatOrchestratorAggregateUsage.test.ts
@@ -0,0 +1,57 @@
+import {createChatOrchestrator} from './chatOrchestrator.js';
+import type {OrchestratorHooks} from './chatOrchestrator.js';
+import {ToolRegistry} from './tools/registry.js';
+import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
+import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+
+const session = (): ChatSession => ({
+  sessionId: 'aggregate-usage-session',
+  userId: 'aggregate-usage-user',
+  entries: [{role: 'user', content: 'Use the tool.', timestamp: '2026-01-01T00:00:00.000Z'}],
+});
+
+const toolCall: MessageChunk = {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}};
+
+const providerFor = (rounds: MessageChunk[][]): AIProvider => {
+  let round = 0;
+  return {
+    async *sendMessage(): AsyncGenerator<MessageChunk> {
+      yield* rounds[round++] ?? [];
+    },
+    async generateStructured<T>(): Promise<T> {
+      return {} as T;
+    },
+  };
+};
+
+const usageStop = (stopReason: string, usage: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});
+
+it('passes the total usage from every provider round to afterModelResponse', async () => {
+  let reported: UsageMetadata | undefined;
+  const hooks: OrchestratorHooks = {
+    afterModelResponse: async (_session, _text, usage) => {
+      reported = usage;
+    },
+  };
+  const registry = new ToolRegistry();
+  registry.register(
+    {name: 'lookup', description: 'Looks up a value.', inputSchema: {type: 'object'}},
+    async () => 'found'
+  );
+
+  const orchestrator = createChatOrchestrator(
+    providerFor([
+      [toolCall, usageStop('tool_use', {inputTokens: 2, outputTokens: 1, totalTokens: 3})],
+      [toolCall, usageStop('tool_use', {inputTokens: 5, outputTokens: 2, totalTokens: 7})],
+      [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 11, outputTokens: 4, totalTokens: 15})],
+    ]),
+    new PromptBuilder({identity: 'Aggregate usage test.'}),
+    registry,
+    {hooks}
+  );
+
+  await orchestrator.processMessage(session());
+
+  expect(reported).toEqual({inputTokens: 18, outputTokens: 7, totalTokens: 25});
+});
